-- Scenario catalog seed (generated by scripts/generate-scenario-seed.ts).
insert into public.scenarios
  (slug, title, category, difficulty, summary, persona, goals, rubric, duration_options)
values
  ('ai-transformation-interview', 'AI transformation lead — first interview', 'career', 'adaptive', 'Walk a recruiter through your experience leading AI adoption in a creative team.', '{"key":"professional_interviewer","name":"Rachel","role":"Senior recruiter, Amsterdam","style":"Friendly but precise. Follows up on vague answers."}'::jsonb, '["Introduce yourself in under a minute","Describe one project with a measurable result","Ask one thoughtful question about the role"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"Easy to follow, one idea per answer."},{"key":"relevance","label":"Relevance","description":"Answers the question that was asked."},{"key":"structured_examples","label":"Structured examples","description":"Situation → action → result, with a concrete detail."},{"key":"language_patterns","label":"Language patterns","description":"Tense control and natural professional phrasing."},{"key":"turn_taking","label":"Turn taking","description":"Answers, then hands the turn back."}]'::jsonb, '{5,10,20}'::integer[]),
  ('founder-investor-pitch', 'Pitch your startup to an angel investor', 'founder', 'medium', 'Explain your value proposition and what makes your product different.', '{"key":"founder_investor","name":"Marcus","role":"Angel investor, London","style":"Curious and direct. Asks about market, pricing and differentiation."}'::jsonb, '["State the problem in one sentence","Use “What makes us different is…”","Handle one pricing follow-up"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"A listener can repeat your pitch."},{"key":"differentiation","label":"Differentiation","description":"A specific, believable difference."},{"key":"language_patterns","label":"Language patterns","description":"Confident, natural business phrasing."}]'::jsonb, '{5,10}'::integer[]),
  ('client-project-briefing', 'Client briefing with scope pushback', 'client', 'hard', 'Clarify deliverables and politely push back on extra scope.', '{"key":"client_stakeholder","name":"Priya","role":"Marketing director, brand client","style":"Busy and opinionated. Pushes for more scope on the same budget."}'::jsonb, '["Summarize the brief back to the client","Say no to extra scope without sounding rude","Agree on a next step"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"Deliverables are unambiguous."},{"key":"politeness","label":"Polite firmness","description":"Pushback that keeps the relationship warm."},{"key":"turn_taking","label":"Turn taking","description":"Listens, then responds."}]'::jsonb, '{10,20}'::integer[]),
  ('festival-small-talk', 'Small talk at a techno festival', 'social', 'easy', 'Chat about music, travel and favorite artists with someone you just met.', '{"key":"friendly_partner","name":"Leo","role":"Fellow festival-goer","style":"Relaxed and chatty. Loves melodic techno."}'::jsonb, '["Use “I''m into…”","Ask two follow-up questions","Suggest meeting again"]'::jsonb, '[{"key":"naturalness","label":"Naturalness","description":"Sounds casual, not scripted."},{"key":"turn_taking","label":"Turn taking","description":"Keeps the chat flowing."}]'::jsonb, '{5,10}'::integer[]),
  ('salary-negotiation', 'Negotiate your job offer', 'career', 'hard', 'You have an offer. Ask for a better package without risking the relationship.', '{"key":"salary_negotiator","name":"Daniel","role":"Head of Design, Berlin scale-up","style":"Warm but budget-conscious. Trades on benefits before salary."}'::jsonb, '["Thank them and show you''re excited about the role","Ask for a higher salary with one concrete reason","Negotiate one non-salary item (remote days, start date or learning budget)"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"The ask is specific: a number or a concrete change."},{"key":"justification","label":"Justification","description":"Backs the ask with value, not need."},{"key":"politeness","label":"Polite firmness","description":"Holds a position while staying positive."},{"key":"language_patterns","label":"Language patterns","description":"Hedging and conditionals: “Would it be possible…”, “If we could…”."}]'::jsonb, '{5,10}'::integer[]),
  ('recruiter-phone-screen', 'Recruiter phone screen for a role abroad', 'career', 'medium', 'A 10-minute screening call: motivation, availability and relocation.', '{"key":"professional_interviewer","name":"Oliver","role":"Tech recruiter, London","style":"Brisk and practical. Checks visa, notice period and motivation."}'::jsonb, '["Explain why you want to work abroad in two sentences","Give your notice period and relocation plans clearly","Ask about the next steps in the process"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"Easy to follow, one idea per answer."},{"key":"relevance","label":"Relevance","description":"Answers the question that was asked."},{"key":"structured_examples","label":"Structured examples","description":"Situation → action → result, with a concrete detail."},{"key":"language_patterns","label":"Language patterns","description":"Tense control and natural professional phrasing."},{"key":"turn_taking","label":"Turn taking","description":"Answers, then hands the turn back."}]'::jsonb, '{5,10}'::integer[]),
  ('defend-a-design-decision', 'Defend a design decision', 'client', 'medium', 'Explain why you chose a design direction and what you''d do if it fails.', '{"key":"product_owner","name":"Hannah","role":"Product owner, fintech app","style":"Analytical. Asks for data and trade-offs, not opinions."}'::jsonb, '["State the decision and the user problem it solves","Support it with one piece of evidence","Offer a fallback or a test plan"]'::jsonb, '[{"key":"clarity","label":"Clarity","description":"Decision, reason and trade-off are easy to follow."},{"key":"structured_examples","label":"Evidence","description":"A concrete data point, test or user quote."},{"key":"language_patterns","label":"Language patterns","description":"Cause and contrast: “because”, “so that”, “whereas”."}]'::jsonb, '{5,10,20}'::integer[]),
  ('ai-meetup-networking', 'Networking at an AI meetup', 'social', 'medium', 'Introduce yourself, talk about AI tools you use and exchange contacts.', '{"key":"friendly_partner","name":"Sofia","role":"Product designer at a Berlin AI meetup","style":"Curious and talkative. Swaps tool tips and job leads."}'::jsonb, '["Introduce what you do in one sentence","Share one AI tool you use and why","Suggest staying in touch (LinkedIn or coffee)"]'::jsonb, '[{"key":"naturalness","label":"Naturalness","description":"Sounds relaxed and genuine."},{"key":"turn_taking","label":"Turn taking","description":"Asks back and builds on the other person''s answers."},{"key":"language_patterns","label":"Language patterns","description":"Small-talk phrases: “What brings you here?”, “I''ve been…”."}]'::jsonb, '{5,10}'::integer[])
on conflict (slug) do update set
  title = excluded.title,
  category = excluded.category,
  difficulty = excluded.difficulty,
  summary = excluded.summary,
  persona = excluded.persona,
  goals = excluded.goals,
  rubric = excluded.rubric,
  duration_options = excluded.duration_options,
  is_active = true;
